// Same layout as Pcie::SystemSlotInfo in pcieslot.hpp (SMBIOS Type 9)
struct SystemSlotInfo
{
    uint8_t type;
    uint8_t length;
    uint16_t handle;
    uint8_t slotDesignation;
    uint8_t slotType;
    uint8_t slotDataBusWidth;
    uint8_t currUsage;
    uint8_t slotLength;
    uint16_t slotID;
    uint8_t characteristics1;
    uint8_t characteristics2;
    uint16_t segGroupNum;
    uint8_t busNum;
    uint8_t deviceNum;
} __attribute__((packed));

void PcieDevice::pcieDeviceInfoUpdate(uint8_t* smbiosTableStorage,
                                      const std::string& motherboard,
                                      const std::string& slotPath)
{
    storage = smbiosTableStorage;
    motherboardPath = motherboard;

    uint8_t* dataIn = getSMBIOSTypePtr(storage, systemSlots);

    if (dataIn == nullptr)
    {
        return;
    }

    for (uint8_t index = 0;
         index < deviceNum ||
         pcieSmbiosType.find(*(dataIn + 5)) == pcieSmbiosType.end();)
    {
        dataIn = smbiosNextPtr(dataIn);
        if (dataIn == nullptr)
        {
            return;
        }
        dataIn = getSMBIOSTypePtr(dataIn, systemSlots);
        if (dataIn == nullptr)
        {
            return;
        }
        if (pcieSmbiosType.find(*(dataIn + 5)) != pcieSmbiosType.end())
        {
            index++;
        }
    }

    auto slotInfo = reinterpret_cast<struct SystemSlotInfo*>(dataIn);

    auto genIt = pcieGenerationTable.find(slotInfo->slotType);
    PCIeGeneration gen = (genIt != pcieGenerationTable.end())
                             ? genIt->second
                             : PCIeGeneration::Unknown;
    PCIeDeviceIface::generationInUse(gen);
    PCIeDeviceIface::generationSupported(gen);

    auto lanesIt = pcieLanesTable.find(slotInfo->slotDataBusWidth);
    size_t lanes = (lanesIt != pcieLanesTable.end()) ? lanesIt->second : 0;
    PCIeDeviceIface::maxLanes(lanes);

    // Not available from SMBIOS Type 9; max() causes bmcweb to omit the field
    PCIeDeviceIface::lanesInUse(std::numeric_limits<size_t>::max());

    PCIeDeviceIface::deviceType(PCIeDeviceType::Unknown);

#ifdef SLOT_DRIVE_PRESENCE
    PCIeDeviceItem::present(
        slotInfo->currUsage == static_cast<uint8_t>(Availability::InUse));
#else
    PCIeDeviceItem::present(true);
#endif

    if (!slotPath.empty())
    {
        std::vector<std::tuple<std::string, std::string, std::string>> assocs;
        assocs.emplace_back("contained_by", "containing", slotPath);
        PCIeDeviceAssoc::associations(assocs);
    }
}

} // namespace smbios
} // namespace phosphor

#include "pcieslot.hpp"

#include <cstdint>
#include <map>

namespace phosphor
{
namespace smbios
{

void Pcie::pcieInfoUpdate(uint8_t* smbiosTableStorage,
                          const std::string& motherboard)
{
    storage = smbiosTableStorage;
    motherboardPath = motherboard;

    uint8_t* dataIn =
        getSMBIOSTypePtr(storage, systemSlots, sizeof(SystemSlotInfo),
                         storage + smbiosTableStorageSize);

    if (dataIn == nullptr)
    {
        return;
    }

    /* offset 5 points to the slot type */
    for (uint8_t index = 0;
         index < pcieNum ||
         pcieSmbiosType.find(*(dataIn + 5)) == pcieSmbiosType.end();)
    {
        dataIn = smbiosNextPtr(dataIn, storage + smbiosTableStorageSize);
        if (dataIn == nullptr)
        {
            return;
        }
        dataIn = getSMBIOSTypePtr(dataIn, systemSlots, sizeof(SystemSlotInfo),
                                  storage + smbiosTableStorageSize);
        if (dataIn == nullptr)
        {
            return;
        }
        if (pcieSmbiosType.find(*(dataIn + 5)) != pcieSmbiosType.end())
        {
            index++;
        }
    }

    auto pcieInfo = reinterpret_cast<struct SystemSlotInfo*>(dataIn);

    pcieGeneration(pcieInfo->slotType);
    pcieType(pcieInfo->slotType, pcieInfo->slotLength);
    pcieLaneSize(pcieInfo->slotDataBusWidth);
    pcieIsHotPluggable(pcieInfo->characteristics2);
    pcieLocation(pcieInfo->slotDesignation, pcieInfo->length, dataIn);

#ifdef SLOT_DRIVE_PRESENCE
    /* Set PCIeSlot presence based on its current Usage */
    Item::present(pcieInfo->currUsage ==
                  static_cast<uint8_t>(Availability::InUse));
#else
    /* Pcie slot is embedded on the board. Always be true */
    Item::present(true);
#endif

    if (!motherboardPath.empty())
    {
        std::vector<std::tuple<std::string, std::string, std::string>> assocs;
        assocs.emplace_back("chassis", "pcie_slots", motherboardPath);
        association::associations(assocs);
    }
}

void Pcie::pcieGeneration(const uint8_t type)
{
    std::map<uint8_t, PCIeGeneration>::const_iterator it =
        pcieGenerationTable.find(type);
    if (it == pcieGenerationTable.end())
    {
        PCIeSlot::generation(PCIeGeneration::Unknown);
    }
    else
    {
        PCIeSlot::generation(it->second);
    }
}

void Pcie::pcieType(const uint8_t type, const uint8_t slotLength)
{
    // Try to find PCIeType in the main table
    auto it = pcieTypeTable.find(type);
    PCIeType pcieSlotType = PCIeType::Unknown;

    if (it != pcieTypeTable.end())
    {
        pcieSlotType = it->second;
    }
    else
    {
        // If not found in `pcieTypeTable`, check `PCIeTypeByLength`
        auto slotIt = PCIeTypeByLength.find(slotLength);
        if (slotIt != PCIeTypeByLength.end())
        {
            pcieSlotType = slotIt->second;
        }
    }

    // Set the slot type
    PCIeSlot::slotType(pcieSlotType);
}

void Pcie::pcieLaneSize(const uint8_t width)
{
    std::map<uint8_t, size_t>::const_iterator it = pcieLanesTable.find(width);
    if (it == pcieLanesTable.end())
    {
        PCIeSlot::lanes(0);
    }
    else
    {
        PCIeSlot::lanes(it->second);
    }
}

void Pcie::pcieIsHotPluggable(const uint8_t characteristics)
{
    /*  Bit 1 of slot characteristics 2 indicates if slot supports hot-plug
     *  devices
     */
    PCIeSlot::hotPluggable(characteristics & 0x2);
}

void Pcie::pcieLocation(const uint8_t slotDesignation, const uint8_t structLen,
                        uint8_t* dataIn)
{
    location::locationCode(positionToString(slotDesignation, structLen, dataIn,
                                            storage + smbiosTableStorageSize));
}

