static void setBaseboardTable(uint8_t* storage, size_t base, uint8_t boardType,
                              uint8_t numContained, uint16_t handle0 = 0)
{
    storage[base + 0] = baseboardType;
    storage[base + 1] = 17;
    storage[base + 2] = 0x2B;
    storage[base + 3] = 0x00;
    for (int i = 4; i <= 12; i++)
        storage[base + i] = 0;
    storage[base + 13] = boardType;
    storage[base + 14] = numContained;
    storage[base + 15] = handle0 & 0xFF;
    storage[base + 16] = (handle0 >> 8) & 0xFF;
    storage[base + 17] = 0;
    storage[base + 18] = 0;
}

static void setStructureWithHandle(uint8_t* storage, size_t base,
                                   uint16_t handle)
{
    storage[base + 0] = chassisType;
    storage[base + 1] = 5;
    storage[base + 2] = handle & 0xFF;
    storage[base + 3] = (handle >> 8) & 0xFF;
    storage[base + 4] = 0;
    storage[base + 5] = 0;
    storage[base + 6] = 0;
}

static void setBaseboardTableWithTwoHandles(uint8_t* storage, uint16_t handle0,
                                            uint16_t handle1)
{
    storage[0] = baseboardType;
    storage[1] = 19;
    storage[2] = 0x2B;
    storage[3] = 0x00;
    storage[13] = static_cast<uint8_t>(Baseboard::BoardType::ProcessorModule);
    storage[14] = 2;
    storage[15] = handle0 & 0xFF;
    storage[16] = (handle0 >> 8) & 0xFF;
    storage[17] = handle1 & 0xFF;
    storage[18] = (handle1 >> 8) & 0xFF;
    storage[19] = 0;
    storage[20] = 0;
}

