TEST(Baseboard, FindIndexOfTypeMatchAndNoMatch)
{
    uint8_t storage[256] = {0};
    // Baseboard (type 2) containing one object with handle 0x1234.
    setBaseboardTable(storage, 0, 6 /*ProcessorModule*/, 1, 0x1234);
