    storage[11] = 0x01;
    storage[50] = 0;
    storage[51] = 0;
    std::string mb = "/xyz/openbmc_project/test/inventory/system";
    std::string assoc = "/xyz/openbmc_project/test/inventory/system/cpu0";
    EXPECT_NO_THROW({
        Cpu cpu(*bus, "/xyz/openbmc_project/test/inventory/system/cpu0", cpuId,
                storage, mb, assoc);
    });
}

