    EXPECT_NE(getInstance(0x30, model606A0, dontWake), nullptr);
    EXPECT_NE(getInstance(0x30, model606C0, dontWake), nullptr);
    EXPECT_NE(getInstance(0x30, model806F0, dontWake), nullptr);
